begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(position('public.care_eligibility_lock()' in pg_get_functiondef('public.save_appointment(uuid,integer,uuid,uuid,timestamptz,integer,text,appointment_status,uuid,text)'::regprocedure))>position('pg_advisory_xact_lock(73260123)' in pg_get_functiondef('public.save_appointment(uuid,integer,uuid,uuid,timestamptz,integer,text,appointment_status,uuid,text)'::regprocedure)) and position('public.care_eligibility_lock()' in pg_get_functiondef('public.save_appointment(uuid,integer,uuid,uuid,timestamptz,integer,text,appointment_status,uuid,text)'::regprocedure))<position('select * into r from appointments' in pg_get_functiondef('public.save_appointment(uuid,integer,uuid,uuid,timestamptz,integer,text,appointment_status,uuid,text)'::regprocedure)),'Compatibility save takes schedule then care before the appointment row');
insert into auth.users(id,email,raw_user_meta_data) values
 ('49000000-0000-4000-8000-000000000001','next-visit-staff@example.test','{"first_name":"Next","last_name":"Staff"}'),
 ('49000000-0000-4000-8000-000000000002','next-visit-vet@example.test','{"first_name":"Next","last_name":"Vet"}');
update profiles set is_active=true where id in('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002');
insert into user_roles(user_id,role) values('49000000-0000-4000-8000-000000000001','STAFF'),('49000000-0000-4000-8000-000000000002','DVM'),('49000000-0000-4000-8000-000000000002','ADMIN') on conflict do nothing;
insert into clients(id,first_name,last_name,full_name,primary_phone,primary_email,preferred_channel) values
 ('49100000-0000-4000-8000-000000000001','Next','Client','Next Client','+12025550197','next-visit-client@example.test','EMAIL');
insert into pets(id,client_id,name,species,breed) values
 ('49200000-0000-4000-8000-000000000001','49100000-0000-4000-8000-000000000001','Next Dog','Dog','Mixed'),
 ('49200000-0000-4000-8000-000000000002','49100000-0000-4000-8000-000000000001','Other Dog','Dog','Mixed');
create temp table fixture(key text primary key,value jsonb);grant all on fixture to authenticated;
create function pg_temp.visit(at text,patient uuid default '49200000-0000-4000-8000-000000000001',state appointment_status default 'SCHEDULED') returns jsonb language sql as $$
 select to_jsonb(save_appointment(auth.uid(),null,null,'49100000-0000-4000-8000-000000000001',patient,at::timestamptz,30,'Next custom',state,'49000000-0000-4000-8000-000000000002','clinic','Synthetic clinic',0,0,null,'Synthetic','{}')) $$;
create function pg_temp.complete(p_key text,action uuid) returns jsonb language sql as $$
 select complete_appointment(auth.uid(),action,(select (value->>'id')::uuid from fixture where fixture.key=p_key),1) $$;
create function pg_temp.decide(p_key text,action uuid,expected integer,p_payload jsonb) returns jsonb language sql as $$
 select save_next_visit_outcome(auth.uid(),action,(select (value#>>'{context,occurrence,id}')::uuid from fixture where fixture.key=p_key),expected,p_payload) $$;
select ok(not has_table_privilege('authenticated','appointment_completion_occurrences','SELECT'),'Completion history is private');
select ok(not has_table_privilege('service_role','appointment_completion_occurrences','INSERT'),'Service cannot manufacture completions');
select ok(not has_table_privilege('authenticated','appointment_next_visit_heads','UPDATE'),'Browser cannot bypass outcome version');
select ok(not has_table_privilege('service_role','appointment_next_visit_heads','UPDATE'),'Service cannot bypass outcome serialization');
select ok(not has_table_privilege('authenticated','appointment_next_visit_decisions','SELECT'),'Decision history is private');
select ok(not has_table_privilege('service_role','appointment_next_visit_decisions','INSERT'),'Service cannot manufacture outcomes');
select ok(not has_table_privilege('authenticated','appointment_next_visit_actions','INSERT'),'Browser cannot manufacture receipts');
select ok(not has_table_privilege('service_role','appointment_next_visit_actions','SELECT'),'Receipts are not exposed through service role');
select ok(not has_function_privilege('anon','complete_appointment(uuid,uuid,uuid,integer)','EXECUTE'),'Anonymous completion denied');
select ok(not has_function_privilege('authenticated','next_visit_occurrence_current(uuid)','EXECUTE'),'Eligibility helper is private');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"49000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(jsonb_array_length(list_pending_next_visits()->'items'),0,'No historical completion backfill');
insert into fixture select 'visit',pg_temp.visit('2031-01-01T16:00:00Z');
select throws_ok($$select complete_appointment('49000000-0000-4000-8000-000000000002',gen_random_uuid(),(select (value->>'id')::uuid from fixture where key='visit'),1)$$,'42501',null,'Actor must match session');
insert into fixture select 'complete',pg_temp.complete('visit','49300000-0000-4000-8000-000000000001');
select is((select value#>>'{appointment,status}' from fixture where key='complete'),'COMPLETED','Completion RPC commits visit');
select is((select value#>>'{context,version}' from fixture where key='complete'),'0','New completion outcome is pending');
select is((select value#>>'{context,occurrence,appointment_version}' from fixture where key='complete'),'2','Exact completed appointment version captured');
select is(pg_temp.complete('visit','49300000-0000-4000-8000-000000000001'),(select value from fixture where key='complete'),'Lost completion response replays without another save');
select is(jsonb_array_length(list_pending_next_visits()->'items'),1,'Pending completion is recoverable independently of calendar date');
select lives_ok($$select save_appointment((select (value->>'id')::uuid from fixture where key='visit'),2,'49100000-0000-4000-8000-000000000001','49200000-0000-4000-8000-000000000001','2031-01-01T16:00:00Z',30,'Next custom','COMPLETED','49000000-0000-4000-8000-000000000002','Notes only')$$,'Completed notes edit remains supported');
select is(jsonb_array_length(list_pending_next_visits()->'items'),1,'Completed notes edit does not create another occurrence');
select throws_ok($$select complete_appointment(auth.uid(),gen_random_uuid(),(select (value->>'id')::uuid from fixture where key='visit'),2)$$,'PT409',null,'Stale completion action rejected');
insert into fixture values('later','{"action":"later","note":"Client will call","followup_on":"2031-01-02","booking":null,"appointment_id":null,"appointment_version":null}');
insert into fixture select 'later-receipt',pg_temp.decide('complete','49300000-0000-4000-8000-000000000002',0,(select value from fixture where key='later'));
select is((select value#>>'{decision,kind}' from fixture where key='later-receipt'),'later','Schedule later is durably attributed');
select is((select value#>>'{decision,actor_id}' from fixture where key='later-receipt'),'49000000-0000-4000-8000-000000000001','Decision keeps actual staff actor');
select is((select value#>>'{occurrence,snapshot,status}' from fixture where key='later-receipt'),'COMPLETED','Deferring does not undo completion');
select is(pg_temp.decide('complete','49300000-0000-4000-8000-000000000002',0,(select value from fixture where key='later')),(select value from fixture where key='later-receipt'),'Exact decision retry returns original receipt');
select throws_ok($$select pg_temp.decide('complete','49300000-0000-4000-8000-000000000002',0,jsonb_set((select value from fixture where key='later'),'{note}','"Changed"'))$$,'23505',null,'Changed work cannot reuse action');
select throws_ok($$select pg_temp.decide('complete',gen_random_uuid(),0,(select value from fixture where key='later'))$$,'PT409',null,'Another tab must review saved outcome version');
insert into fixture select 'declined',pg_temp.decide('complete','49300000-0000-4000-8000-000000000003',1,'{"action":"declined","note":"Client declined","followup_on":null,"booking":null,"appointment_id":null,"appointment_version":null}');
select is((select value#>>'{decision,kind}' from fixture where key='declined'),'declined','Deferred visit can be explicitly declined later');
select is(jsonb_array_length(list_pending_next_visits()->'items'),0,'Resolved decline leaves pending queue');
select throws_ok($$select pg_temp.decide('complete',gen_random_uuid(),2,(select value from fixture where key='later'))$$,'PT409',null,'Final outcome cannot be silently replaced');
select lives_ok($$select cancel_appointment((select (value->>'id')::uuid from fixture where key='visit'),3)$$,'Source can be canceled without deleting history');
select is(read_next_visit_context((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='complete'))->>'current','false','Canceled source occurrence is historical');
select is(pg_temp.complete('visit','49300000-0000-4000-8000-000000000001'),(select value from fixture where key='complete'),'Saved completion receipt survives subsequent cancellation');
select lives_ok($$select save_appointment((select (value->>'id')::uuid from fixture where key='visit'),4,'49100000-0000-4000-8000-000000000001','49200000-0000-4000-8000-000000000001','2031-01-01T16:00:00Z',30,'Next custom','COMPLETED','49000000-0000-4000-8000-000000000002','Completed again')$$,'A later real completion is a separate occurrence');
insert into fixture select 'recomplete',jsonb_build_object('context',(list_pending_next_visits()->'items'->0));
select isnt((select value#>>'{context,occurrence,id}' from fixture where key='recomplete'),(select value#>>'{context,occurrence,id}' from fixture where key='complete'),'Distinct transition gets a distinct durable occurrence');
insert into fixture select 'future-one',pg_temp.visit('2031-01-02T16:00:00Z');
insert into fixture select 'future-two',pg_temp.visit('2031-01-03T16:00:00Z');
insert into fixture select 'other-patient',pg_temp.visit('2031-01-04T16:00:00Z','49200000-0000-4000-8000-000000000002');
insert into fixture select 'future-page',list_next_visit_future_appointments((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='recomplete'),null,null,null,1);
select is(jsonb_array_length((select value->'items' from fixture where key='future-page')),1,'Future page is bounded');
select ok((select value->'next' from fixture where key='future-page')<>'null'::jsonb,'Future page exposes explicit continuation');
select is((select value->'items'->0->>'id' from fixture where key='future-page'),(select value->>'id' from fixture where key='future-one'),'Future list excludes source completion and other patient');
select is(jsonb_array_length(list_next_visit_future_appointments((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='recomplete'),(select (value->>'as_of')::timestamptz from fixture where key='future-page'),(select (value#>>'{next,at}')::timestamptz from fixture where key='future-page'),(select (value#>>'{next,id}')::uuid from fixture where key='future-page'),1)->'items'),1,'Future cursor retains fixed server as-of');
select throws_ok($$select list_next_visit_future_appointments((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='recomplete'),null,now(),gen_random_uuid(),1)$$,'23514',null,'Continuation cannot replace its fixed as-of');
select throws_ok($$select pg_temp.decide('recomplete',gen_random_uuid(),0,jsonb_build_object('action','existing','note','','followup_on',null,'booking',null,'appointment_id',(select value->>'id' from fixture where key='other-patient'),'appointment_version',1))$$,'23514',null,'Other patient future booking cannot resolve this visit');
insert into fixture select 'existing',pg_temp.decide('recomplete','49300000-0000-4000-8000-000000000004',0,jsonb_build_object('action','existing','note','Already scheduled','followup_on',null,'booking',null,'appointment_id',(select value->>'id' from fixture where key='future-one'),'appointment_version',1));
select is((select value#>>'{decision,appointment_id}' from fixture where key='existing'),(select value->>'id' from fixture where key='future-one'),'Existing booking is linked explicitly');
select is((select value#>>'{decision,booking_receipt,existing}' from fixture where key='existing'),'true','Existing booking receipt does not claim new creation');
insert into fixture select 'source-two',pg_temp.visit('2031-01-05T16:00:00Z');
insert into fixture select 'complete-two',pg_temp.complete('source-two',gen_random_uuid());
insert into fixture values('custom-values','{"client_id":"49100000-0000-4000-8000-000000000001","pet_id":"49200000-0000-4000-8000-000000000001","scheduled_at":"2031-01-06T16:00:00Z","duration_minutes":30,"appointment_type":"Next follow-up","assigned_dvm_id":"49000000-0000-4000-8000-000000000002","visit_type":"clinic","address_snapshot":"Synthetic clinic","travel_before_minutes":0,"travel_after_minutes":0,"resource_name":null,"notes":"Synthetic","reminder_offsets":[]}');
insert into fixture select 'book-values',jsonb_build_object('action','book','note','Time reviewed','followup_on',null,'booking',jsonb_build_object('mode','custom','values',(select value from fixture where key='custom-values')),'appointment_id',null,'appointment_version',null);
insert into fixture select 'booked',pg_temp.decide('complete-two','49300000-0000-4000-8000-000000000005',0,(select value from fixture where key='book-values'));
select is((select value#>>'{decision,kind}' from fixture where key='booked'),'booked','Custom booking and outcome commit together');
select is(pg_temp.decide('complete-two','49300000-0000-4000-8000-000000000005',0,(select value from fixture where key='book-values')),(select value from fixture where key='booked'),'Custom lost-response replay returns exact booking');
select throws_ok($$select pg_temp.decide('complete-two',gen_random_uuid(),0,(select value from fixture where key='book-values'))$$,'PT409',null,'Fresh action cannot create second follow-up');
insert into fixture select 'source-three',pg_temp.visit('2031-01-07T16:00:00Z');
insert into fixture select 'complete-three',pg_temp.complete('source-three',gen_random_uuid());
select throws_ok($$select pg_temp.decide('complete-three','49300000-0000-4000-8000-000000000006',0,(select value from fixture where key='book-values'))$$,'23P01',null,'Booking collision rolls back outcome too');
select is(read_next_visit_context((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='complete-three'))->>'version','0','Conflict leaves outcome unresolved');
select is(recover_next_visit_action(auth.uid(),'49300000-0000-4000-8000-000000000006','decide',jsonb_build_object('occurrence_id',(select value#>>'{context,occurrence,id}' from fixture where key='complete-three'),'expected_version',0,'values',(select value from fixture where key='book-values'))),null::jsonb,'Rolled-back collision has no saved receipt');
select throws_ok($$select pg_temp.decide('complete-three',gen_random_uuid(),0,jsonb_set((select value from fixture where key='later'),'{action}','12'))$$,'23514',null,'Action must be a typed decision');
select throws_ok($$select pg_temp.decide('complete-three',gen_random_uuid(),0,jsonb_set((select value from fixture where key='later'),'{followup_on}','"2000-01-01"'))$$,'23514',null,'Later review date cannot be in the past');
select is(jsonb_array_length(list_next_visit_due_care((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='complete-three'))->'items'),0,'No clinical dates are inferred from visit completion');
select throws_ok($$select list_next_visit_due_care((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='complete-three'),'{}')$$,'23514',null,'Due-care pagination requires exact cursor fields');
-- Read context consumes reviewed facts without advancing their clinical sources.
select set_config('request.jwt.claims','{"sub":"49000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into fixture values('care-default','{"care_key":"next-reviewed","name":"Synthetic next reviewed care","care_kind":"wellness","interval_amount":1,"interval_unit":"months","anchor_mode":"fixed_schedule","month_end":"clamp","active":true,"review_note":"Synthetic reviewed calendar"}');
select save_recurring_care_template(gen_random_uuid(),'49500000-0000-4000-8000-000000000001',null,(select value from fixture where key='care-default'));
select save_recurring_care_template(gen_random_uuid(),'49500000-0000-4000-8000-000000000002',null,(select value||'{"care_key":"next-proposed"}' from fixture where key='care-default'));
insert into fixture values('care-values','{"template_id":"49500000-0000-4000-8000-000000000001","template_version":1,"name":"Synthetic next reviewed care","interval_amount":1,"interval_unit":"months","anchor_mode":"fixed_schedule","month_end":"clamp","anchor_on":"2026-01-31","due_on":"2026-02-28","status":"current","reminders_enabled":false,"override_reason":"","review_note":"Synthetic reviewed patient calendar","replace_anchor_evidence":false}');
select save_patient_care_plan(gen_random_uuid(),'49500000-0000-4000-8000-000000000003','49200000-0000-4000-8000-000000000001',null,(select value from fixture where key='care-values'));
select save_patient_care_plan(gen_random_uuid(),'49500000-0000-4000-8000-000000000004','49200000-0000-4000-8000-000000000001',null,(select value||'{"template_id":"49500000-0000-4000-8000-000000000002","status":"proposed"}' from fixture where key='care-values'));
select save_patient_lab_order('49500000-0000-4000-8000-000000000005','49200000-0000-4000-8000-000000000001',null,'{"test_name":"Synthetic planned next CBC","status":"planned","due_date":"2031-01-01"}','');
select save_patient_lab_order('49500000-0000-4000-8000-000000000006','49200000-0000-4000-8000-000000000001',null,'{"test_name":"Synthetic ordered next Chemistry","status":"ordered","due_date":"2031-01-02"}','');
select set_config('request.jwt.claims','{"sub":"49000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fixture select 'due-context',list_next_visit_due_care((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='complete-three'));
select is(jsonb_array_length((select value->'items' from fixture where key='due-context')),3,'Only current reviewed care plus explicitly planned/ordered labs appear');
select is((select value#>>'{items,0,review_state}' from fixture where key='due-context'),'reviewed','Current care recommendation retains reviewed status');
select is((select value#>>'{items,1,review_state}' from fixture where key='due-context'),'planned','Planned lab is not promoted to reviewed recommendation');
insert into fixture select 'due-page',list_next_visit_due_care((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='complete-three'),null,1);
select is(jsonb_array_length(list_next_visit_due_care((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='complete-three'),(select value->'next' from fixture where key='due-page'),1)->'items'),1,'Due-care continuation is bounded and advances');
reset role;
select set_config('request.jwt.claims','{}',true);
update profiles set is_active=false where id='49000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"49000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(jsonb_array_length(list_next_visit_due_care((select (value#>>'{context,occurrence,id}')::uuid from fixture where key='complete-three'))->'items'),2,'A care approval that is no longer source-current needs review');
reset role;
select is((select count(*) from appointment_completion_occurrences),4::bigint,'All real completion transitions retained; notes did not create one');
select is((select count(*) from appointments where appointment_type='Next follow-up'),1::bigint,'Custom exact retry creates only one follow-up');
select is((select count(*) from appointment_next_visit_decisions),4::bigint,'Later, decline, existing and booking preserve immutable outcome history');
select throws_ok($$update appointment_completion_occurrences set snapshot='{}' where actor_id='49000000-0000-4000-8000-000000000001'$$,'23514',null,'Completion snapshot immutable');
select throws_ok($$delete from appointment_next_visit_decisions where actor_id='49000000-0000-4000-8000-000000000001'$$,'23514',null,'Decision history cannot be deleted');
select set_config('request.jwt.claims','{}',true);
insert into appointments(id,client_id,pet_id,scheduled_at,duration_minutes,appointment_type,status,visit_type) values
 ('49400000-0000-4000-8000-000000000001','49100000-0000-4000-8000-000000000001','49200000-0000-4000-8000-000000000001','2031-01-08T16:00:00Z',30,'Trusted historical completion','COMPLETED','clinic'),
 ('49400000-0000-4000-8000-000000000002','49100000-0000-4000-8000-000000000001','49200000-0000-4000-8000-000000000001','2031-01-09T16:00:00Z',30,'Retained unassigned','SCHEDULED','clinic');
select is((select actor_id from appointment_completion_occurrences where appointment_id='49400000-0000-4000-8000-000000000001'),null::uuid,'Trusted operator capture does not invent an actor');
select is((select snapshot->'assigned_dvm_id' from appointment_completion_occurrences where appointment_id='49400000-0000-4000-8000-000000000001'),'null'::jsonb,'Trusted unassigned completion remains readable');
update profiles set is_active=false where id='49000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"49000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select list_pending_next_visits()$$,'42501',null,'Inactive staff cannot read queue');
select throws_ok($$select pg_temp.complete('visit','49300000-0000-4000-8000-000000000001')$$,'42501',null,'Saved receipt cannot bypass current access');
select * from finish();
rollback;
